def reprendre_prix(apps, schema_editor):
    """Le prix unique « prix_carburant_litre » devient la première entrée de
    l'historique (diesel et essence), puis le paramètre est supprimé."""
    import datetime
    Parametre = apps.get_model('parametrage', 'Parametre')
    PrixCarburant = apps.get_model('carburant', 'PrixCarburant')
    p = Parametre.objects.filter(cle='prix_carburant_litre').first()
    try:
        prix = float(p.valeur) if p else 700
    except (TypeError, ValueError):
        prix = 700
    for type_carburant in ('diesel', 'essence'):
        PrixCarburant.objects.get_or_create(
            type_carburant=type_carburant, date_effet=datetime.date(2000, 1, 1),
            defaults={'prix': prix, 'commentaire': 'Reprise du prix par défaut'},
        )
    Parametre.objects.filter(cle='prix_carburant_litre').delete()


def restaurer_parametre(apps, schema_editor):
    Parametre = apps.get_model('parametrage', 'Parametre')
    PrixCarburant = apps.get_model('carburant', 'PrixCarburant')
    dernier = PrixCarburant.objects.filter(type_carburant='diesel').order_by('-date_effet').first()
    Parametre.objects.update_or_create(cle='prix_carburant_litre', defaults={
        'valeur': str(dernier.prix if dernier else 700), 'type_valeur': 'int', 'categorie': 'alertes'})


